import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:shared_preferences/shared_preferences.dart';

// Generated by `flutterfire configure` on each machine; not in git
// (see CLAUDE.md > App setup on a new machine).
import 'firebase_options.dart';
import 'screens/home_screen.dart';
import 'theme.dart';
import 'watch_store.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized(); // needed before using plugins in main()
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  // The Inter font's license has to ship with it; this lists it on the licenses page.
  LicenseRegistry.addLicense(() async* {
    final text = await rootBundle.loadString('assets/fonts/Inter-OFL.txt');
    yield LicenseEntryWithLineBreaks(const ['Inter font'], text);
  });

  // Load the saved watch list before the first frame, so bells show the right state.
  final watches = WatchStore(await SharedPreferences.getInstance());
  runApp(LootAlertApp(watches: watches));
}

class LootAlertApp extends StatelessWidget {
  const LootAlertApp({super.key, required this.watches});

  final WatchStore watches;

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'D2 Loot Alert',
      debugShowCheckedModeBanner: false,
      theme: buildTheme(),
      // `builder` wraps the whole navigator, so pushed screens (a category, About)
      // can reach the watch list too, not just the home screen.
      builder: (context, child) => WatchScope(store: watches, child: child!),
      home: const HomeScreen(),
    );
  }
}
